-- Second migration (T238): the Seller table, generated by Prisma from schema.prisma, plus the
-- hand-written contact CHECK at the end. The three contact columns hold ciphertext.

-- CreateTable
CREATE TABLE "Seller" (
    "id" TEXT NOT NULL,
    "fullName" TEXT NOT NULL,
    "email" TEXT,
    "phone" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Seller_pkey" PRIMARY KEY ("id")
);



-- AddCheck (hand-written): a seller has an email or a phone. An empty field stays NULL, so the
-- database can check this even though the values are encrypted.
ALTER TABLE "Seller" ADD CONSTRAINT "Seller_contact_check" CHECK ("email" IS NOT NULL OR "phone" IS NOT NULL);
